    "name": "dataset"
  },
  "padding": {
    "left": 0,
    "right": 4,
    "top": 0,
    "bottom": 2
  },
  "transform": [
    {
      "window": [
        {
          "op": "row_number",
          "as": "week_number"
        }
      ],
      "sort": [
        {
          "field": "Week",
          "order": "ascending"
        }
      ]
    },
    {
      "calculate": "indexof([''Part Ramadan'', ''Full Ramadan''], datum[''Week type'']) >= 0 ? datum[''week_number''] : null",
      "as": "ramadan_number"
    },
    {
      "joinaggregate": [
        {
          "op": "min",
          "field": "ramadan_number",
          "as": "ramadan_first"
        },
        {
          "op": "max",
          "field": "ramadan_number",
          "as": "ramadan_last"
        },
        {
          "op": "max",
          "field": "Axis max",
          "as": "axis_top"
        },
        {
          "op": "valid",
          "field": "Spent",
          "as": "spent_weeks"
        }
      ]
    },
    {
      "window": [
        {
          "op": "lag",
          "field": "Spent",
          "as": "spent_prev"
        },
        {
          "op": "lead",
          "field": "Spent",
          "as": "spent_next"
        },
        {
          "op": "lag",
          "field": "Label",
          "as": "label_prev"
        },
        {
          "op": "lead",
          "field": "Label",
          "as": "label_next"
        }
      ],
      "sort": [
        {
          "field": "Week",
          "order": "ascending"
        }
      ]
    },
    {
      "calculate": "!isValid(datum[''Label'']) ? null : isValid(datum[''label_prev'']) ? ''left'' : isValid(datum[''label_next'']) ? ''right'' : datum[''spent_prev''] > datum[''Label''] && !(datum[''spent_next''] > datum[''Label'']) ? ''left'' : datum[''spent_next''] > datum[''Label''] && !(datum[''spent_prev''] > datum[''Label'']) ? ''right'' : ''centre''",
      "as": "label_side"
    },
    {
      "calculate": "datum[''week_number''] >= datum[''ramadan_first''] && datum[''week_number''] <= datum[''ramadan_last'']",
      "as": "in_band"
    },
    {
      "calculate": "pbiFormat(datum[''Spent''], ''#,0.00'')",
      "as": "spent_text"
    },
    {
      "calculate": "isValid(datum[''Before'']) ? pbiFormat(datum[''Before''], ''#,0.00'') : ''None: no week with this number a year before''",
      "as": "before_text"
    },
    {
      "calculate": "isValid(datum[''Before'']) && datum[''Before''] > 0 ? pbiFormat(round(1000 * (datum[''Spent''] / datum[''Before''] - 1)) / 1000, ''+0.0%;−0.0%;0.0%'') : ''None''",
      "as": "change_text"
    }
  ],
